function wireApiList(root, rerender){
  if(!root) return;
  root.querySelectorAll('[data-apidel]').forEach(function(b){ b.addEventListener('click',function(ev){ ev.stopPropagation(); removeApiEntry(b.getAttribute('data-apidel')); toast('API removed'); if(rerender) rerender(); }); });
  root.querySelectorAll('[data-apiuse]').forEach(function(b){ b.addEventListener('click',function(){ setActiveApi(b.getAttribute('data-apiuse')); toast('Active API switched'); if(rerender) rerender(); }); });
  root.querySelectorAll('[data-apitest]').forEach(function(b){ b.addEventListener('click',function(ev){
    ev.stopPropagation();
    var e=apiEntryById(b.getAttribute('data-apitest')); if(!e) return;
    b.disabled=true; b.textContent='Testing…';
    setApiTestMsg('Testing '+apiEntryLabel(e)+'…');
    testApiEntry(e).then(function(r){
      setApiTestMsg(r.ok
        ? '✓ '+apiEntryLabel(e)+' is working'
        : '✗ '+apiEntryLabel(e)+' is not working — GptOpen didn’t answer through this key');
      if(rerender) rerender();
    });
  }); });
}
/* =============== Test API ===============
   The Test button on each added key: first the provider's own
   model list is asked (issuer endpoint only), then a one-line
   ping is tried with EVERY model on that key, in order, until
   one answers — a single model failing never fails the test.
   A pass marks the key Working, keeps the model that answered
   as the key's model, makes it the active API, and the result
   text shows under the list; only when every model on the key
   has failed does a fail show, with the last provider error.
   Works the same for every provider. */
var apiTestMsgText='';
function setApiTestMsg(t){
  apiTestMsgText=t;
  var el=document.getElementById('apiTestMsg')||document.getElementById('plusTestMsg');
  if(el) el.textContent=t;
}
function apiHost(e){
  var p=e&&API_PROVIDERS[e.provider];
  try{ return new URL((e&&e.base)||(p?p.base:'')).host; }catch(err){ return (e&&e.base)||''; }
}
function pingApi(entry, modelOverride){
  var p=API_PROVIDERS[entry.provider]; if(!p) return Promise.resolve({ok:false, msg:'Provider not recognised'});
  var useModel=modelOverride||entry.model||p.defModel;
  var url, headers, body;
  if(p.type==='gemini'){
    url=p.base+'/models/'+encodeURIComponent(useModel)+':generateContent';
    headers={'Content-Type':'application/json','x-goog-api-key':entry.key};
    body={contents:[{role:'user',parts:[{text:'Reply with OK'}]}], generationConfig:{temperature:0, maxOutputTokens:8}};
  } else if(p.type==='anthropic'){
    url=p.base+'/messages';
    headers={'Content-Type':'application/json','x-api-key':entry.key,'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true'};
    body={model:useModel, max_tokens:8, messages:[{role:'user', content:'Reply with OK'}]};
  } else if(entry.provider==='mistral' && mistralAgentOn()){
    /* Mistral Agent ping: the Agents endpoint, with the saved
       agent id — the agent answers, not a bare model. */
    url=p.base+'/agents/completions';
    headers={'Content-Type':'application/json','Authorization':'Bearer '+entry.key};
    body={agent_id:state.mistralAgentId, messages:[{role:'user', content:'Reply with OK'}]};
  } else {
    url=(entry.base||p.base).replace(/\/$/,'')+'/chat/completions';
    headers={'Content-Type':'application/json','Authorization':'Bearer '+entry.key};
    body={model:useModel, messages:[{role:'user', content:'Reply with OK'}], temperature:0, max_tokens:8};
  }
  return fetchWithTimeout(url,{method:'POST', headers:headers, body:JSON.stringify(body)}, 30000)
    .then(function(r){ return r.json().then(function(j){ return {ok:r.ok, j:j, status:r.status}; }).catch(function(){ return {ok:r.ok, j:null, status:r.status}; }); })
    .then(function(res){
      if(res.ok) return {ok:true};
      var em='';
      try{ var ej=res.j&&res.j.error; em=(ej&&(ej.message||ej))||(res.j&&res.j.message)||''; if(typeof em!=='string') em=JSON.stringify(em); }catch(e){}
      var kind=apiFailureKind(res.status, res.j);
      return {ok:false, kind:kind, status:res.status, j:res.j, modelError:isModelFailure(res.status, res.j),
        msg:(kind==='quota'? 'Quota / rate limit reached (HTTP '+res.status+')' : providerErrorMessage(res.status, res.j))};
    })
    .catch(function(){ return {ok:false, kind:'error', msg:'Network or CORS — the provider could not be reached from this page'}; });
}
function testApiEntry(entry){
  if(!entry || !entry.provider) return Promise.resolve({ok:false, msg:'Provider not recognised — this key is not sent anywhere.'});
  entry.status='checking';
  function done(ok, msg, kind){
    entry.status= ok? 'ok' : (kind||'error');
    entry.detail= ok? 'Working — tested' : msg;
    if(ok){
      state.activeApiId=entry.id; syncLegacyApi(); setApiHealth('ok');
    }
    return {ok:ok, msg:msg, kind:kind||(ok?'':'error')};
  }
  return apiFetchModels(entry).then(function(models){
    if(models && models.length) entry.models=models;
    /* Explicit pick: try ONLY that model — never auto-advance
       past a user's own choice; its real error is reported. */
    var explicitM=getExplicitModel(entry.provider);
    var isExplicit=entry.explicit || !!explicitM;
    var candidates;
    if(isExplicit) candidates=[explicitM || entry.model].filter(Boolean);
    else {
      candidates=apiModelCandidates(entry);
      if(!candidates.length) candidates=[entry.model||(API_PROVIDERS[entry.provider]||{}).defModel].filter(Boolean);
      candidates=candidates.slice(0, MODEL_AUTO_CAP);
    }
    var last={ok:false, msg:'No model could be tried', kind:'error'};
    function tryPing(i){
      if(i>=candidates.length) return Promise.resolve(done(false, last.msg, last.kind));
      return pingApi(entry, candidates[i]).then(function(r){
        if(r.ok){
          entry.model=candidates[i];
          /* Auto-selected working model: persist per provider so
             it keeps working with zero manual picking. An
             explicit pick is left exactly as the user set it. */
          if(!isExplicit) setWorkingModel(entry.provider, candidates[i]);
          return done(true,'Working');
        }
        last=r;
        /* Only a MODEL failure auto-advances on Test; other
           failures (quota, auth, network) report as they are. */
        if(!isModelFailure(r.status||0, r.msg||'') && r.kind!=='quota' && candidates.length>1 && i+1<candidates.length && !/model/i.test(r.msg||'')) return tryPing(i+1);
        return tryPing(i+1);
      });
    }
    return tryPing(0);
  });
}
/* =============== Composer API box — select / add / retest ===============
   When no API is working the type box is replaced by the API box
   (markup: #apiBox inside #composerZone). Its search button (and
   its status line) opens the API picker sheet: the shared relay,
   every added API (Use / Test), every free-key site (Get key), and
   the paste-a-key box — all searchable. Its circular button, where
   Send normally sits, retests everything in attempt order and
   stops at the first API that answers; that answer flips the
   health to ok and the normal type box flows back by itself. */
var apiTesting=false;
function composerApiMode(){
  if(apiIncomplete()) return true;
  /* A success newer than the last failure wins: models that are
     actually working never show the not-working box. */
  if(apiOkAt && apiOkAt>=apiFailAt) return false;
  return state.apiHealth==='error' || state.apiHealth==='quota';
}
function updateComposerMode(){
  var z=$('#composerZone'); if(!z) return;
  z.classList.toggle('api-mode', composerApiMode());
  if(composerApiMode()) updateApiBoxLabel();
  updateModelLabel();
}
function updateApiBoxLabel(){
  var t=$('#apiBoxTitle'), s=$('#apiBoxSub'); if(!t||!s) return;
  if(apiTesting){ t.textContent='Testing…'; s.textContent='Trying the Gptopen Model and your added keys'; return; }
  if(relayGone && !apiEntries().length && state.relayOn){ t.textContent='Gptopen Model didn\u2019t answer'; s.textContent='Tap retry'; return; }
  if(state.apiHealth==='quota'){ t.textContent='Limit reached'; s.textContent='Lots of people are chatting — use your own key, or retry in a moment'; return; }
  if(apiEntries().length){ t.textContent='No API working'; s.textContent='GptOpen didn’t answer — tap to select or add an API'; return; }
  t.textContent='No API set up'; s.textContent='Tap to add your own key, or use the Gptopen Model';
}
function pingRelay(entry, modelOverride){
  var p=API_PROVIDERS[entry.provider];
  var body={provider:entry.provider, model:(modelOverride || getExplicitModel(entry.provider) || getWorkingModel(entry.provider) || (p? p.defModel : entry.model)), messages:[{role:'user', content:'Reply with OK'}], temperature:0, max_tokens:8};
  if(entry.provider==='mistral' && mistralAgentOn()) body.agent_id=state.mistralAgentId;
  return fetchWithTimeout('/api/relay',{method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)}, 30000)
    .then(function(r){ var hdr=r.headers.get('x-axo-relay'); return r.json().then(function(j){ return {ok:r.ok, j:j, status:r.status, relayHdr:hdr}; }).catch(function(){ return {ok:r.ok, j:null, status:r.status, relayHdr:hdr}; }); })
    .then(function(res){
      /* Gone ONLY when nothing relay-like answered at all: no
         JSON body and no relay header (a static host's 404 page,
         or a refused connection). Any JSON — even a provider
         error the relay passed through — proves the relay is
         live; only this provider failed. */
      if(!relayAnswered(res)){ relayGone=true; return {ok:false, gone:true, msg:'Relay didn\u2019t answer'}; }
      relayGone=false; relayStrikes=0;
      /* Any 2xx from the relay means the provider answered —
         the content of a one-word ping is irrelevant (reasoning
         models may return it empty), so res.ok alone is success. */
      if(res.ok) return {ok:true};
      var kind=apiFailureKind(res.status, res.j);
      /* The provider's real error, plainly — a relayed provider
         404 is a provider/model error, never "no relay". */
      return {ok:false, kind:kind, status:res.status, j:res.j, modelError:isModelFailure(res.status, res.j), msg: res.status===501? 'Not set on the server (HTTP 501)' : providerErrorMessage(res.status, res.j)};
    })
    .catch(function(){ relayStrikes++; if(relayStrikes>=2) relayGone=true; return {ok:false, gone:relayStrikes>=2, msg:'Relay didn\u2019t answer'}; });
}
/* Test one relay provider with always-on auto-advance: walk its
   ordered candidates (cap MODEL_AUTO_CAP), persist the model
   that answers per provider, and respect an explicit pick (only
   that model is tried; its real error is returned). */
function testRelayEntry(entry){
  if(!entry || !entry.provider || entry.provider==='auto') return pingRelay(entry);
  var explicitM=getExplicitModel(entry.provider);
  var candidates= explicitM? [explicitM] : modelCandidatesFor(entry).slice(0, MODEL_AUTO_CAP);
  if(!candidates.length) candidates=[(API_PROVIDERS[entry.provider]||{}).defModel].filter(Boolean);
  var last={ok:false, msg:'No model could be tried', kind:'error'};
  function step(i){
    if(i>=candidates.length) return Promise.resolve(last);
    return pingRelay(entry, candidates[i]).then(function(r){
      if(r.ok){
        if(!explicitM) setWorkingModel(entry.provider, candidates[i]);
        entry.model=candidates[i];
        return {ok:true, model:candidates[i]};
      }
      last=r;
      if(r.gone) return last;
      return step(i+1);
    });
  }
  return step(0);
}
function testAllApis(){
  if(apiTesting) return;
  /* Every test re-probes the relay from scratch: a "gone"
     verdict from an earlier round never carries over. */
  relayGone=false; relayStrikes=0;
  var entries=apiAttemptOrder();
  if(!entries.length){ toast('Add an API key first'); openApiPicker(); return; }
  apiTesting=true;
  var rb=$('#apiBoxRetry'); if(rb) rb.classList.add('testing');
  updateApiBoxLabel();
  var sawQuota=false;
  function finish(ok, msg){
    apiTesting=false; if(rb) rb.classList.remove('testing');
    if(ok){ setApiHealth('ok'); toast(msg||'API working'); }
    else { setApiHealth(sawQuota? 'quota':'error', 'Test failed'); toast(msg||'No API answered — select or add one'); }
    updateComposerMode();
  }
  function step(i){
    if(i>=entries.length){
      finish(false, (relayGone && !apiEntries().length)? 'The Gptopen Model didn\u2019t answer — tap retry' : (sawQuota? 'Every API is at its limit right now' : 'No API answered — select or add one'));
      return;
    }
    var e=entries[i];
    if(e.relay){
      if(relayGone){ step(i+1); return; }
      testRelayEntry(e).then(function(r){
        if(r.ok) finish(true, 'Gptopen Model is working');
        else { if(r.kind==='quota') sawQuota=true; step(i+1); }
      });
      return;
    }
    testApiEntry(e).then(function(r){
      if(r.ok) finish(true, apiEntryLabel(e)+' is working');
      else { if(r.kind==='quota') sawQuota=true; step(i+1); }
    });
  }
  step(0);
}
/* Choose a different free API (from the picker or an error
   message): the picked shared provider is tried FIRST from now
   on (state.relayPick drives apiAttemptOrder), the relay verdict
   is reset, and the provider is pinged on the spot — a working
   answer flips health to ok and the normal type box returns. If
   the current chat is waiting on a failed request, it is retried
   straight away with the new choice first. */
function useRelayProvider(pid){
  if(!pid) return;
  state.relayPick=pid; state.relayOn=true; relayGone=false; relayStrikes=0;
  if(typeof saveLocalSoon==='function') saveLocalSoon();
  var entry={id:'relay-'+pid, relay:true, provider:pid, base:'', model:(API_PROVIDERS[pid]||{}).defModel, models:(RELAY_FALLBACK_MODELS[pid]||[]), key:'', status:'relay', detail:'Gptopen Model'};
  toast('Trying GptOpen…');
  /* Provider select runs auto-advance too: candidates are tried
     in order until one answers, and the working one is kept. */
  testRelayEntry(entry).then(function(r){
    if(r.ok){ setApiHealth('ok'); toast('GptOpen is working'); updateComposerMode(); updateModelLabel(); return; }
    if(r.gone){ toast('The Gptopen Model didn\u2019t answer just now — tap retry'); }
    else toast('GptOpen didn’t answer just now — tap retry');
    updateComposerMode();
  });
}
function apiPickRowsHTML(q){
  /* ONE built-in model, shown under ONE name — Gptopen Model.
     Behind it the app quietly tries every route the server has
     (every Vercel variable set, each with fallback models, then
     a final server-side sweep), but none of that is listed here:
     no provider names, no per-model rows, no details. Below it,
     only the user's OWN added keys, then the paste-a-key box in
     the sheet itself — that is the whole picker. */
  var out='';
  var rSub= relayGone? 'Didn\u2019t answer last time — tap Test' : (state.relayOn? 'Built in · ready to chat' : 'Off — tap to turn on');
  out+='<div class="api-item"><div class="api-row"><span class="api-dot '+(relayGone?'error':(state.relayOn?'ok':''))+'"></span><span class="api-meta"><span class="api-name">Gptopen Model</span><span class="api-sub">'+esc(rSub)+'</span></span><button class="api-use" data-pickrelay="1">'+(state.relayOn?'Test':'Turn on')+'</button></div></div>';
  var a=activeApiEntry();
  apiEntries().forEach(function(e){
    var name=apiEntryLabel(e);
    var st=e.status==='ok'?'Ready':e.status==='quota'?'Quota reached':e.status==='error'?'Not working':e.status==='checking'?'Detecting…':e.status==='unknown'?'Provider not recognised':e.status==='unverified'?'Added — checks on test':'Added';
    out+='<div class="api-item"><div class="api-row'+(a&&e.id===a.id?' active':'')+'"><span class="api-dot '+esc(e.status||'')+'"></span><span class="api-meta"><span class="api-name">'+esc(name)+'</span><span class="api-sub">'+esc(apiKeyMask(e))+' · '+esc(st)+'</span></span><button class="api-use" data-picktest="'+e.id+'">Test</button>'+(a&&e.id===a.id? '<span class="api-active-tag">Active</span>' : '<button class="api-use" data-pickuse="'+e.id+'">Use</button>')+'</div></div>';
  });
  return out;
}
function openApiPicker(){
  openSheet('<h3>GptOpen</h3><p class="sub">Your own API key first — or the built-in Gptopen Model.</p>'
    +'<div class="ownapi-card">'
    +'<div class="ownapi-head"><span class="ownapi-ic">'+I.key+'</span><span class="ownapi-meta"><span class="ownapi-title">Your own API</span><span class="ownapi-sub">Your models · your limits · encrypted on this device</span></span><span class="ownapi-badge">Top pick</span></div>'
    +'<div class="field"><input id="apiPickKey" type="password" placeholder="Paste any API key — provider detected automatically" autocomplete="off" aria-label="Your API key"></div>'
    +'<button class="btn-primary" id="apiPickAdd">Add my API key</button>'
    +'<button class="btn-ghost" id="apiPickFree">Get a free key</button>'
    +'</div>'
    +'<div class="api-or"><span></span>Built-in &amp; your keys<span></span></div>'
    +'<div id="apiPickList">'+apiPickRowsHTML('')+'</div>');
  var list=$('#apiPickList');
  function wireRows(){
    list.querySelectorAll('[data-pickuse]').forEach(function(b){ b.addEventListener('click',function(){ setActiveApi(b.getAttribute('data-pickuse')); closeSheet(); testAllApis(); }); });
    list.querySelectorAll('[data-picktest]').forEach(function(b){ b.addEventListener('click',function(){
      var e=apiEntryById(b.getAttribute('data-picktest')); closeSheet(); if(!e) return;
      toast('Testing '+apiEntryLabel(e)+'…');
      testApiEntry(e).then(function(r){
        if(r.ok){ setApiHealth('ok'); toast(apiEntryLabel(e)+' is working'); }
        else { setApiHealth(r.kind==='quota'?'quota':'error'); toast('GptOpen didn’t answer — try again'); }
        updateComposerMode();
      });
    }); });
    list.querySelectorAll('[data-pickrelay]').forEach(function(b){ b.addEventListener('click',function(){
      if(!state.relayOn){ state.relayOn=true; state.relayAutoV3=true; saveLocalSoon(); }
      closeSheet(); testAllApis();
    }); });
  }
  wireRows();
  $('#apiPickAdd').addEventListener('click',function(){
    var k=$('#apiPickKey').value.trim();
    if(!k){ toast('Paste a key first'); return; }
    var btn=this; btn.disabled=true; btn.textContent='Detecting…';
    addApiKey(k).then(function(e){
      closeSheet();
      if(e && e.agent){ toast('Mistral Agent ID saved — Agent API on'); return; }
      toast('Added — testing…'); testAllApis();
    });
  });
  $('#apiPickFree').addEventListener('click',function(){ closeSheet(); openSettings('freekeys'); });
}
/* Sidebar motion — buttery, one continuous flow, fully optimized:
   - Fully closed, the sidebar is display:none (its controls are out
     of the tree, as before). The old hitch was paying its first
     layout + paint DURING the opening slide — that is now avoided
     two ways: an idle warm-up pass (sbWarm) pre-lays-out and
     pre-paints the menu off-screen whenever it is closed and idle,
     and the run itself starts two frames out (double rAF) so the
     one display:flex layout lands in a pre-animation frame, never
     mid-slide.
   - Both layers then move together as pure compositor transforms
     (translate3d only — a straight slide; the 34px curve is the
     peeking card's fixed shape, set inline in the start frame,
     never animated), sidebar and stage in the same frame, same
     easing, no gaps.
   - A drag release passes the distance it still has to travel, so
     the settle run is only as long as the remaining flow — never a
     fresh full-length run that crawls the last few pixels.
   - Timers are kept and cleared so a fast re-tap never fights a
     stale timeout, and an interrupted run retargets from wherever
     the layers currently are. */
var sbWarmT=null;
function sbWarm(){
  if(window.innerWidth>=820 || sbOpen()) return;
  if(sbWarmT) return;
  sbWarmT=setTimeout(function(){
    sbWarmT=null;
    if(sbOpen() || window.innerWidth>=820) return;
    /* One hidden pass: lay the menu out and paint it once (it sits
       translated off-screen, under the stage, visibility hidden),
       then back to display:none. Style/layout caches and the
       raster stay warm, so the next real open is a pure move. */
    sidebar.style.visibility='hidden'; sidebar.style.display='flex';
    void sidebar.offsetWidth;
    requestAnimationFrame(function(){ requestAnimationFrame(function(){
      if(!sbOpen()){ sidebar.style.display='none'; sidebar.style.visibility=''; }
    }); });
  }, 900);
}
var SB_MS=360, sbAnimT=null, sbHideT=null;
/* The open card's paint (peek background, left hairline, soft
   shadow) as INLINE styles, applied by setSidebar in the exact
   frame the transform starts moving and cleared only when a
   close has fully landed. As a .sb-open class rule it landed a
   frame before the transform — the fullscreen chat flashed into
   card styling, then slid: the open/close glitch. */
function sbStageCard(on){
  if(on){ stage.style.background='var(--peek)'; stage.style.borderLeft='1px solid var(--border2)'; stage.style.boxShadow='-16px 0 48px rgba(0,0,0,.75)'; }
  else{ stage.style.background=''; stage.style.borderLeft=''; stage.style.boxShadow=''; }
}
function setSidebar(open, animate, dur){
  if(sbAnimT){ clearTimeout(sbAnimT); sbAnimT=null; }
  if(sbHideT){ clearTimeout(sbHideT); sbHideT=null; }
  app.classList.remove('dragging');
  var ms=(typeof dur==='number' && dur>0)? Math.round(dur) : SB_MS;
  if(window.innerWidth>=820){
    app.classList.toggle('anim', !!animate);
    sidebar.style.transform=''; stage.style.transform=''; stage.style.borderRadius=''; scrim.style.opacity=''; sidebar.style.display=''; sidebar.style.visibility='';
    app.classList.toggle('sb-closed', !open); app.classList.toggle('sb-open', open);
    if(animate){ app.style.setProperty('--sb-ms', ms+'ms'); sbAnimT=setTimeout(function(){ app.classList.remove('anim'); app.style.removeProperty('--sb-ms'); }, ms+30); }
    return;
  }
  app.classList.toggle('sb-open', open); app.classList.toggle('sb-closed', !open);
  if(open){
    sidebar.style.display='flex'; sidebar.style.visibility='';
    /* MENU COLOUR FIX: the sidebar head avatar is first rendered at
       boot while the sidebar is hidden (mobile), and some phone
       WebViews never repaint that SVG's gradient fills when the menu
       opens — the avatar shape then shows as a dark / wrong-coloured
       blob in the menu. Re-render the head avatar fresh on every
       open, while the sidebar is visible, so its shape always paints
       in its real colours. (Cached: a no-op unless the agent changed.) */
    try{ if(typeof syncSidebarAgent==='function') syncSidebarAgent(); }catch(e){}
  }
  var sbT=open?'translate3d(0,0,0)':'translate3d(-102%,0,0)';
  /* Curved peek (original shape, kept exactly) with a STRAIGHT
     slide: the stage pushes right by exactly the sidebar width —
     no scale at all — already wearing its fixed 34px curve; the
     scrim is a transparent tap shield over the peeking card only. */
  var stT=open?'translate3d('+sbWidth()+'px,0,0)':'translate3d(0,0,0)';
  var stR=open?'34px 0 0 34px':'0px';
  scrim.style.opacity='0';
  if(!animate){
    app.classList.remove('anim'); app.style.removeProperty('--sb-ms');
    sidebar.style.transform=sbT; stage.style.transform=stT; stage.style.borderRadius=stR;
    sbStageCard(open);
    app.classList.toggle('sb-live', open);
    scrim.style.left=open?sbWidth()+'px':'0px';
    if(!open) sidebar.style.display='none';
    return;
  }
  app.style.setProperty('--sb-ms', ms+'ms');
  app.classList.add('anim');
  /* Commit the start frame, then apply the target on the NEXT
     frame. One tap must open the menu with that tap, so the
     target never waits on a second frame: a busy main thread (or
     a WebView that throttles rAF right after a tap) could drop
     or starve that second frame and the tap looked ignored. A
     60ms safety timer applies the same target if the frame has
     not landed yet, so the tap always lands. */
  void stage.offsetWidth;
  var sbApplied=false;
  function sbApplyTarget(){
    if(sbApplied) return; sbApplied=true;
    sidebar.style.transform=sbT; stage.style.transform=stT;
    /* The curve lands WITH the first moving frame on open — same
       frame as the transform, never a frame earlier (the cut-at-
       the-curve flash). On close the radius is NOT zeroed here:
       the card slides straight back still wearing its curve, and
       sbHideT clears it only once the stage is fullscreen again,
       so the corner never collapses or looks cut mid-close. */
    if(open){ stage.style.borderRadius=stR; sbStageCard(true); }
    scrim.style.left=open?sbWidth()+'px':'0px';
  }
  requestAnimationFrame(sbApplyTarget);
  setTimeout(sbApplyTarget, 0);
  setTimeout(sbApplyTarget, 60);
  if(!open){
    /* Stage slides back over the sidebar first; only once it has
       fully covered it is the sidebar hidden, so the close never
       looks like a disappearance. */
    sbHideT=setTimeout(function(){ if(!sbOpen()){ sbStageCard(false); stage.style.borderRadius=''; sidebar.style.display='none'; sbWarm(); } }, ms+30);
  }
  sbAnimT=setTimeout(function(){
    app.classList.remove('anim'); app.style.removeProperty('--sb-ms');
    /* Keep the stage's layer promotion while the menu is open
       (sb-live): releasing it at identity only, never at the
       open pose, whose re-raster was the post-open
       shimmer across the chat screen. */
    app.classList.toggle('sb-live', !!sbOpen());
  }, ms+30);
}
(function(){
  var startX=0, startY=0, dragging=false, wasOpen=false, W=0, dragLock=null;
  var dragRaf=0, dragDx=0, dragVel=0, dragLastX=0, dragLastT=0;
  var sbDragClickAt=0;
  document.addEventListener('pointerdown',function(e){
    if(window.innerWidth>=820) return;
    if(e.target.closest('#settingsView,.sheet,.menu-pop')) return;
    if(e.target.closest('.chat-row')) return; /* rows run their own swipe (delete/open) */
    wasOpen=sbOpen(); W=sbWidth();
    if(!wasOpen){
      if(e.target.closest('button,input,textarea,select,a')) return;
      /* Swipe right anywhere on the chat background opens the menu —
         not just from the left edge — smooth and easy. Gestures that
         start on a message stay with the message (its own swipe to
         reply), and buttons/inputs are already excluded above. */
      if(e.target.closest('.msg')) return;
      if(!e.target.closest('#stage')) return;
    }
    if(wasOpen){
      /* CLOSE SWIPE FIX (right-to-left): the old code returned for
         EVERY touch inside #sidebar and for every x < sidebar
         width, so a close drag could only ever start on the narrow
         peeking strip at the right edge — a right-to-left swipe on
         the open menu itself (where a closing swipe naturally
         starts) was discarded before it began, and the menu never
         closed by swipe. The asymmetry is gone: a close drag may
         now start from the menu itself as well as from the peeking
         stage. Inside the menu only real text entry (the Search
         field) is excluded; chat rows keep their own swipe
         (excluded above), and vertical scrolling is still safe —
         the direction lock in pointermove cancels the drag the
         moment a gesture proves vertical, and a plain tap never
         locks, so taps on menu buttons still click normally. A
         click that trails a locked horizontal drag is swallowed
         (see sbDragClickAt), so a swipe that starts on a menu
         button closes the menu instead of also pressing it. */
      if(e.target.closest('#sidebar')){
        if(e.target.closest('input,textarea,select')) return;
      } else {
        if(e.clientX<W-8) return;
        /* The peeking stage is covered by the scrim, which is the
           usual target here; a direct stage button keeps its tap. */
        if(e.target!==scrim && e.target.closest('button,input,textarea,select,a')) return;
      }
    }
    startX=e.clientX; startY=e.clientY; dragging=true; dragLock=null;
    dragDx=0; dragVel=0; dragLastX=e.clientX; dragLastT=Date.now();
    /* FLICKER FIX: nothing visual is armed yet. The dragging state
       (display:flex, layer promotion, transition kill) is applied
       only when the gesture proves itself horizontal (dragArm in
       pointermove). Arming it on EVERY pointerdown — and then
       running a full settle animation on release — meant every
       plain tap and every vertical scroll on the chat screen
       toggled the stage's layers and glass, which read as the
       chat screen flickering and glitching. */
  },{passive:true});
  function dragArm(){
    sidebar.style.display='flex'; sidebar.style.visibility='';
    app.classList.add('dragging');
    sidebar.classList.add('noanim'); stage.classList.add('noanim');
  }
  function applyDragFrame(){
    dragRaf=0; if(!dragging || dragLock!=='h') return;
    var dx=dragDx;
    var base=wasOpen?0:-W; var pos=Math.max(-W, Math.min(0, base+dx));
    var prog=W? (pos+W)/W : 0; /* 0 = closed, 1 = fully open */
    sidebar.style.transform='translate3d('+pos+'px,0,0)';
    /* Straight drag, same as the animated run: pure translate, no
       scale, and the curve does NOT grow with the drag — it is
       the card's fixed 34px shape from the first moving frame
       (0 only at the fully-closed rest position). */
    stage.style.transform='translate3d('+(pos+W)+'px,0,0)';
    stage.style.borderRadius=prog>0? '34px 0 0 34px' : '0px';
    scrim.style.opacity='0';
    scrim.style.left=(pos+W)+'px';
  }
  document.addEventListener('pointermove',function(e){
    if(!dragging) return;
    var dx=e.clientX-startX, dy=e.clientY-startY;
    /* Velocity (px/ms) from the last move — a quick flick opens or
       closes even when the distance is short, like Apple's drawer. */
    var now=Date.now(), dt=now-dragLastT;
    if(dt>0){ dragVel=0.7*dragVel + 0.3*((e.clientX-dragLastX)/dt); dragLastX=e.clientX; dragLastT=now; }
    /* Direction lock: nothing moves until the gesture proves itself
       horizontal. A vertical-dominant move cancels the drag for good
       and hands the gesture back to the scroller under the finger, so
       scrolling up or down is never fought or frozen mid-swipe. */
    if(!dragLock){
      /* Vertical-dominant: cancel silently. Nothing was armed, so
         there is nothing to undo and NO settle animation — the
         scroller under the finger simply keeps the gesture. */
      if(Math.abs(dy)>10 && Math.abs(dy)>=Math.abs(dx)*1.15){ dragging=false; return; }
      if(Math.abs(dx)>10 && Math.abs(dx)>Math.abs(dy)*1.15){ dragLock='h'; dragArm(); }
      else return;
    }
    /* Flow without missed frames: pointermove can fire faster than
       the screen refreshes, so the style write is coalesced into ONE
       requestAnimationFrame per frame using the latest position. */
    dragDx=dx;
    if(!dragRaf) dragRaf=requestAnimationFrame(applyDragFrame);
  },{passive:true});
  function up(e){
    if(!dragging) return; dragging=false;
    if(dragRaf){ cancelAnimationFrame(dragRaf); dragRaf=0; }
    /* Released without ever locking horizontal — a plain tap or a
       vertical scroll. Nothing was armed and no transform ever
       moved, so there is nothing to settle: the old code ran a
       full no-op setSidebar animation here after every tap on the
       chat screen, toggling layer promotion for ~390ms each time. */
    if(dragLock!=='h'){ dragLock=null; return; }
    dragLock=null;
    /* The release of a real drag is followed by one synthetic
       click on whatever the finger started on (the scrim, or a
       menu button the close swipe began on). That click must not
       fire: on the scrim it would force-close even when the drag
       settled on staying open, and on a menu button it would press
       the button behind the swipe. Swallow exactly that one. */
    sbDragClickAt=Date.now();
    app.classList.remove('dragging');
    sidebar.classList.remove('noanim'); stage.classList.remove('noanim');
    /* A swipe-left-to-open gesture (below) may have just opened the
       menu during this same touch — do not let this handler's release
       math close it again. */
    if(window.__axoSwipeLeftAt && Date.now()-window.__axoSwipeLeftAt<700) return;
    var dx=e.clientX-startX;
    var open;
    if(dragVel>0.45) open=true;
    else if(dragVel<-0.45) open=false;
    else open=wasOpen ? dx>-W*0.2 : dx>W*0.2;
    /* Continuous flow: the settle run covers ONLY the distance left
       to travel, shortened further on a fast flick — the finger's
       motion hands straight over to the animation with no restart
       and no slow crawl across the last few pixels. */
    var prog=W? (wasOpen? (W+dx)/W : dx/W) : 0; prog=Math.max(0, Math.min(1, prog));
    var remain=open? (1-prog) : prog;
    var dur=Math.max(130, Math.min(SB_MS, SB_MS*remain*1.1));
    if(Math.abs(dragVel)>0.45) dur=Math.min(dur, 200);
    setSidebar(open,true,dur);
  }
  document.addEventListener('pointerup',up,{passive:true});
  document.addEventListener('click',function(e){
    if(sbDragClickAt && Date.now()-sbDragClickAt<400){ sbDragClickAt=0; e.preventDefault(); e.stopPropagation(); }
  },true);
  document.addEventListener('pointercancel',function(){ if(dragging){ var wasLocked=dragLock==='h'; dragging=false; dragLock=null; if(dragRaf){ cancelAnimationFrame(dragRaf); dragRaf=0; } app.classList.remove('dragging'); sidebar.classList.remove('noanim'); stage.classList.remove('noanim'); if(wasLocked) setSidebar(wasOpen,true);} });
  scrim.addEventListener('click',function(){ setSidebar(false,true); });
})();
/* Pull-to-refresh / reload protection is CSS-only on purpose:
   html, body and every scroller carry overscroll-behavior: contain /
   none and the page itself never scrolls (body overflow hidden, #app
   fixed), so an edge swipe cannot chain to the page or reload it.
   The old JS guard preventDefault-ed touchmove at a scroller's edges;
   on mobile browsers that cancels the REST of the gesture too, which
   is exactly what froze scrolling up/down and made lists feel stuck.
   No JS ever preventDefaults a vertical scroll gesture now. */
/* =============== Menus & sheets =============== */
var pop=$('#popMenu');
/* The element that opened the pop menu. The outside-tap closer must
   NOT close the menu when the tap lands on its own anchor button:
   that pointerdown used to close it, and the anchor's click handler
   then reopened it — which is why clicking the dots button while
   its menu was open reopened the menu instead of toggling it shut. */
var popAnchor=null;
function closePop(){ pop.classList.remove('show'); pop.innerHTML=''; popAnchor=null; }
function openPop(anchorRect, items, anchorEl){
  popAnchor=anchorEl||null;
  pop.innerHTML=items.map(function(it){
    if(it.sep) return '<div class="msep"></div>';
    return '<button data-pi="'+it.id+'" class="'+(it.danger?'danger':'')+'">'+(it.icon||'')+'<span>'+esc(it.label)+'</span>'+(it.dot?'<span class="mdot2"></span>':'')+'</button>';
  }).join('');
  pop.classList.add('show');
  var w=236, left=Math.min(anchorRect.right-w, window.innerWidth-w-8); if(left<8) left=8;
  var top=anchorRect.bottom+8, est=items.length*46+14;
  if(top+est>window.innerHeight-10) top=Math.max(8, anchorRect.top-est-8);
  pop.style.left=left+'px'; pop.style.top=top+'px'; pop.style.width=w+'px';
  pop.querySelectorAll('button').forEach(function(b){
    b.addEventListener('click',function(){ var id=b.getAttribute('data-pi'); closePop(); handlePop(id); });
  });
}
document.addEventListener('pointerdown',function(e){
  if(!pop.classList.contains('show')) return;
  if(pop.contains(e.target)) return;
  if(popAnchor && popAnchor.contains(e.target)) return; /* the anchor's own click toggles */
  closePop();
});
var popCtx=null;
function handlePop(id){
  var ctx=popCtx||{}; popCtx=null;
  if(id==='temp'){ toggleTemp(); }
  else if(id==='settings'){ openSettings('list'); }
  else if(id==='split'){ if(ctx.chatId && ctx.chatId!==state.currentId){ if(state.splitId===ctx.chatId) exitSplit(); else enterSplit(ctx.chatId); } else if(state.splitId) exitSplit(); else { var t=chats.filter(function(c){return c.id!==state.currentId;})[0]; if(t) enterSplit(t.id); } }
  else if(id==='openchat'){ openChat(ctx.chatId); }
  else if(id==='rename'){ renameChat(ctx.chatId); }
  else if(id==='delete'){ askDelete(ctx.chatId); }
  else if(id==='clear'){ var c=chatById(ctx.chatId||state.currentId); if(c){ c.messages=[]; renderAll(); toast('Chat cleared'); } }
  else if(id==='share'){ toast('Nothing to share from a static preview'); }
}
var sheet=$('#sheet'), sheetScrim=$('#sheetScrim');
var sheetCloseTimer=null;
function openSheet(html){
  if(sheetCloseTimer){ clearTimeout(sheetCloseTimer); sheetCloseTimer=null; }
  sheet.innerHTML='<div class="grab"></div>'+html; sheet.classList.add('show'); sheetScrim.classList.add('show');
}
function closeSheet(){
  sheet.classList.remove('show'); sheetScrim.classList.remove('show');
  /* Destroy the sheet's content once it has slid away — including
     any code-preview iframe and its srcdoc — so a closed preview
     leaves nothing behind that a keyboard open/close (which lifts
     fixed elements by --kbFixed) could ever show again. The sheet
     is also visibility:hidden whenever it is not .show. */
  if(sheetCloseTimer) clearTimeout(sheetCloseTimer);
  sheetCloseTimer=setTimeout(function(){
    sheetCloseTimer=null;
    if(!sheet.classList.contains('show')) sheet.innerHTML='';
  }, 420);
}
sheetScrim.addEventListener('click',closeSheet);
function detailSheet(title, bullets){
  openSheet('<h3>'+esc(title)+'</h3><p class="sub">Full detail</p><ul>'+bullets.map(function(b){return '<li>'+esc(b)+'</li>';}).join('')+'</ul><button class="btn-ghost" id="sheetCloseBtn">Close</button>');
  $('#sheetCloseBtn').addEventListener('click',closeSheet);
}
var DETAILS={
  apis:{t:'API Keys & Automatic Failover', b:['Just paste a key — the provider, base URL and model are detected and selected automatically. Nothing else to fill in.','There are no model names to pick anywhere: the model behind each key is chosen automatically and silently, and GptOpen is the only model identity you ever see.','Add as many keys as you like, from any supported provider: OpenAI, Anthropic, Google Gemini, OpenRouter, Groq, xAI, DeepSeek, NVIDIA, Mistral, Together, Hugging Face, Cohere, GitHub Models, or another OpenAI-compatible key. Free keys: the Free API keys page (in APIs & Providers) lists every site that gives a key away free, with its Vercel variable name.','Mistral Agent: paste an agent id (ag_…, created in Mistral console → Agents) into the Mistral Agent ID field — or paste it into the key box, it is recognised automatically — and Mistral chats use the Agents API by themselves, no switch. The agent brings its own saved instructions and tools (web search, code interpreter, document library). Clear the id to go back to normal Mistral chat.','Sending tries your active key first with its chosen model, then every other model on that key, then the next key and every model on it, and so on through all keys and all their models. An error is only shown when every model on every key has failed.','Keys and chats are saved locally on this device and restored automatically on every open. Keys are stored encrypted (AES-GCM, sealed under a device key that never leaves this device), are never shown after saving — only the provider and last 4 digits appear — and are never included in backups.','Default model: AxoChat can also chat through its built-in Gptopen Model \u2014 this site\u2019s own server relay (POST /api/relay), sending no key at all. The relay has exactly two providers, Groq and OpenRouter, and reads their keys from the Vercel project\u2019s environment variables (GROQ_API_KEY, OPENROUTER_API_KEY), server-side only, so those keys are never in the app or sent to the browser. Turn it on and read the full setup under APIs & Providers \u2192 Gptopen Model.','Without a key or the relay, replies come from the built-in local reply engine.']},
  freekeys:{t:'Free API Keys', b:['Every site listed gives you a key for free — a free tier, free models, or a free trial key. On each provider card, “Get a free API key” opens that provider\u2019s own site; “Use my API key” opens the key box in APIs & Providers, where the pasted key is detected automatically.','AxoChat’s default model, the Gptopen Model, is built in — chatting works out of the box. It runs on exactly two providers, Groq and OpenRouter. When lots of people are using it and the default limit is over, the chat says so and offers the same two actions: use your own API key, or get a free one from this list.','Variable names (for the app relay, in Vercel \u2192 Settings \u2192 Environment Variables, Production, then redeploy): Groq GROQ_API_KEY \u00b7 OpenRouter OPENROUTER_API_KEY. Those are the only two the relay reads.','Free means limited: rate limits, only some models free, or trial credits. It is never unlimited for everyone, and the default-model endpoint can be used by anyone who finds it — watch usage and spending on the provider side.','No key is ever baked into this app, plain or encrypted: anyone running the app could extract it. Keys live either sealed on your own device, or only on the server behind the relay.']},
  usage:{t:'Usage & Limits', b:['Pick the API you have at the top — the page then shows that API only.','This session counts are counted by the app itself, request by request: requests sent, replies received, failures, quota hits, and the token totals your provider returns with each reply. They reset when the page reloads, like the rest of this preview.','OpenRouter limit: tap Check live usage & limit and the app asks OpenRouter directly, with your saved key, how much this key has used, its limit and what remains. Nothing is estimated.','Google Gemini and custom endpoints do not offer a per-key limit check the app can call, so their limits live on the provider side — the page says so instead of inventing a number, and still shows your status and session counts.']},
  connectors:{t:'Connectors & Online Search', b:['Online Search is the only connector in this build.','When it is on, /search looks up live sources on Wikipedia and the open web.']},
  memory:{t:'Local Memory System', b:['Everything you say in any chat is saved to memory automatically, locally in this app, always \u2014 in detail: the message with its date and time, the chat and the agent, plus a short summary of each reply, in a time-stamped log kept on this device. A rolling summary (how much, since when, main topics, stated preferences, latest entries) is rebuilt and saved locally too, and is read with the matching entries before every reply so answers stay personal.','Before every reply, the saved memory is searched by the incoming message\u2019s keywords, and the reply is built using the related memories found.','Memory never holds keys, secrets, emails or phone numbers — those are stripped out before a note is saved.','Turn it off any time and saving and searching both stop. The + sheet Memory switch and this switch always match.']},
  appearance:{t:'Appearance & Liquid Glass', b:['The phone preview at the top shows the agent avatar, its name label and your bubbles exactly as they will look in chat.','Chat theme is a row of colour circles — White is the default — and it recolours your bubbles and accents across the app.','Avatar size is Small, Medium, Large, Extra large or Hidden, and it sets the agent head size in chat.','Mode is System, Light or Dark; System follows your device setting.','Red appears only for delete and error states.']},
  agent:{t:'Agent', b:['The Agent page is the main agent\u2019s own page: avatar with the pencil menu (Change avatar / Edit name), name, live status, and tabs for Today, Approvals history, Reminders + Daily, and the profile with its VIBE and the SOUL / MEMORY cards.','Sub-agents live under it: the Sub-agents page lists every agent, and the New sub-agent page creates one with its own name, avatar, instructions and memory.','Any agent can be made the main agent at any time from its menu on the Sub-agents page.']},
  agents:{t:'Agents', b:['Settings \u2192 Agents opens the Agent page — the main agent\u2019s page with Today, Approvals, Reminders + Daily, and its profile.','Under it, the Sub-agents page holds the full agents list: create as many agents as you like and chat with any of them.','Each agent has its own name, avatar, custom instructions and custom memory.','Any agent can be made the main agent at any time from its menu.','History and memory are shared by all agents by default; turn on individual history or memory for one agent in its Edit page and only that agent keeps its own.','Animation speed for the Agents UI lives on the Sub-agents page — drag the slider slowly and the live preview changes as you drag.']},
  code:{t:'Code Mode & Play-First Preview', b:['Code replies arrive in a preview box, never written out in full down the chat: the full code sits inside the box and you scroll inside it to read all of it.','HTML code gets Code / Preview tabs in the box header — Preview runs the page inside the same box, and you scroll inside it too.','Full (or Preview full size) opens the code or the preview full size, on its own screen, where the code scrolls and the preview fills the screen.','Play First opens the box on Preview; Code First opens it on Code.']},
  skills:{t:'Skill Library (22 Built-In Skills)', b:['Each skill is one job: a document, a deck, a test pass, a theme.','Use /skill <name> to apply one skill to the next reply, or run a skill directly with its own command.','get-more-perspectives: an advisory panel (Operator, Skeptic, Visionary, Customer Advocate, Finance Mind) that commits to a vote before you decide. Custom panels persist for the session.','match-my-writing-style: drafts in your voice, learned only from your own writing in this app and samples you paste — never from incoming mail, and never a Gmail or Drive scan in this local app. Drafts only; it never sends.','focus-my-energy: matches tasks to your energy (sharp, steady, fried) — Deep Work, Steady Work, Low Drain — with one clear DO NOW. A hard deadline today overrides energy matching.','Disabled skills are skipped by the router.']},
  commands:{t:'Slash Commands', b:['Type / in the composer and the command box appears above it.','Tap a command to run it, or keep typing to filter the list.','/split opens the chosen chat beside your current one, top and bottom.']},
  safety:{t:'Privacy & Key Safety', b:['Your key is used only for calls to the provider you picked.','Never paste a key into a chat message — keys belong in the Model section of the + sheet.']},
  reset:{t:'Delete everything & reset', b:['This deletes everything AxoChat has saved on this device, in this browser, for this site — all chats and messages, all agents with their avatars, instructions and per-agent memory, every saved API key (including its sealed vault copy and the vault database), System files and Library files, saved memory, goals, scheduled messages and notifications, and all app settings such as theme, accent and appearance.','It cannot be undone. There is no restore from the app after a reset — download a backup first from History & backups if you want a copy of your chats, agents and files (backups never include API keys).','The app restarts as a brand-new user: the intro is shown again, asking what to call you, with the default agent and the default settings.','Only this device and this browser origin are cleared. AxoChat’s default models on the server are not affected — they are not your data and you do not need a key for them after the reset.']}
};
function qBtn(key){ return '<span class="qbtn" role="button" tabindex="0" data-q="'+key+'" aria-label="More detail">?</span>'; }
document.addEventListener('click',function(e){
  var q=e.target.closest('[data-q]'); if(q){ var d=DETAILS[q.getAttribute('data-q')]; if(d) detailSheet(d.t,d.b); }
});
/* =============== Chat actions =============== */
function toggleTemp(){
  /* The ONLY function that can turn Temporary chat on. It is wired
     solely to Temporary chat's own toggles: the header pill button
     while it shows the Temporary icon, and the "Temporary chat" row
     in the dots menu. No New chat path calls this. */
  state.temp=!state.temp; updateTargetLine(); updateTempIcon();
  /* Re-render the chat + head right away so the agent avatar
     starts (or stops) its eyes-closed-and-peeking loop the
     moment Temporary chat toggles — renderMain swaps the
     empty-chat hero, renderAgentHead the pinned top head. */
  renderMain(); if(typeof renderAgentHead==='function') renderAgentHead();
  toast(state.temp?'Temporary chat on — main chat stays continuous':'Temporary chat off');
}
function openChat(id){
  if(!chatById(id)) return;
  state.replyTo=null; if(typeof renderReplyBar==='function') renderReplyBar(); closeMsgMenu();
  if(typeof setTabSel==='function') setTabSel('main');
  state.currentId=id; setSidebar(false,true); closeSettings(true); renderAll();
}
function newChat(){
  /* Starting a new chat NEVER turns Temporary chat on — it clears
     it, so a fresh chat never inherits the temp banner or state.
     Temporary chat turns on only from toggleTemp() (its own toggle). */
  state.temp=false;
  state.replyTo=null; if(typeof renderReplyBar==='function') renderReplyBar(); closeMsgMenu();
  var tb=$('#tempBtn'); if(tb) tb.classList.remove('temp-on');
  var c={id:'c'+(++uid), title:'New chat', messages:[]};
  var nca=(typeof chatAgent==='function')? chatAgent() : null;
  if(nca && nca.individualHistory) c.agentId=nca.id;
  chats.splice(1,0,c); state.currentId=c.id; state.splitId=null;
  setSidebar(false,true); closeSettings(true); renderAll();
  $('#chatInput').focus();
}
function enterSplit(id){
  if(id===state.currentId){ toast('Pick a different chat for split'); return; }
  state.splitId=id; state.splitActive='bottom'; closeSettings(true); renderAll();
  toast('Split screen on — tap a pane, then type');
}
function exitSplit(){ state.splitId=null; renderAll(); updateTargetLine(); }
function renameChat(id){
  var c=chatById(id); if(!c) return;
  openSheet('<h3>Rename chat</h3><div class="field"><label>Title</label><input id="rnInput" type="text" value="'+esc(c.title)+'"></div>'
    +'<button class="btn-primary" id="rnSave">Save</button><button class="btn-ghost" id="rnCancel">Cancel</button>');
  $('#rnSave').addEventListener('click',function(){ var v=$('#rnInput').value.trim(); if(v){ c.title=v; renderAll(); } closeSheet(); });
  $('#rnCancel').addEventListener('click',closeSheet);
}
function askDelete(id){
  var c=chatById(id); if(!c) return;
  openSheet('<h3>Delete this chat?</h3><p class="sub">'+esc(c.title)+' will be removed. This cannot be undone.</p>'
    +'<button class="btn-danger" id="delYes">Delete</button><button class="btn-ghost" id="delNo">Cancel</button>');
  $('#delYes').addEventListener('click',function(){
    chats=chats.filter(function(x){return x.id!==id;});
    if(state.splitId===id) state.splitId=null;
    if(state.currentId===id) state.currentId='main';
    closeSheet(); renderAll(); toast('Chat deleted');
  });
  $('#delNo').addEventListener('click',closeSheet);
}
document.addEventListener('click',function(e){
  var b=e.target.closest('[data-act]');
  if(b){
    var m=null, mChat=null;
    for(var i=0;i<chats.length && !m;i++){ var fm=findMsg(chats[i], b.getAttribute('data-id')); if(fm){ m=fm; mChat=chats[i]; } }
    if(m){
      var act=b.getAttribute('data-act');
      if(act==='copy' && m.code) copyText(m.code.body);
      else if(act==='copyai') copyText(m.text);
      else if(act==='play' && m.code) openCodeFull(m, 'preview');
      else if(act==='expandcode' && m.code) openCodeFull(m, (b.closest('.codeblock') && b.closest('.codeblock').getAttribute('data-codeview')==='preview')? 'preview' : 'code');
      else if(act==='canvasopen' && m.code) openCanvasFull(m);
      else if(act==='retrylast'){
        /* Retry: drop this error message, RESET the relay
           detection (a transient failure must never stick for
           the whole session), and run the exact same request
           again — the last user message is still in the chat. */
        var rix=mChat.messages.indexOf(m); if(rix>=0) mChat.messages.splice(rix,1);
        relayGone=false; relayStrikes=0;
        setApiHealth('changed');
        renderAll();
        if(providerRouteOn()) callProvider(mChat, null);
        else toast('Add an API key or turn on the Gptopen Model first');
      }
      else if(act==='choosediff') openApiPicker();
      else if(act==='usemykey') openSettings('apis');
      else if(act==='getfreekey') openSettings('freekeys');
      else if(act==='avconfirm' && m.avatarProposal && !m.avatarProposal.resolved) confirmAvatarProposal(mChat, m);
      else if(act==='avcancel' && m.avatarProposal && !m.avatarProposal.resolved){ m.avatarProposal.resolved='cancelled'; renderAll(); toast('Okay — the avatar was not changed'); }
    }
  }
  var st=e.target.closest('[data-starter]');
  if(st) sendText(st.getAttribute('data-starter'));
});
function copyText(t){
  if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(t).then(function(){ toast('Copied'); },function(){ toast('Copy failed'); }); }
  else toast('Copy unavailable here');
}
function openPreview(code){
  /* Play always opens the preview FULL SIZE now (the old half-
     height sheet is gone): the full-size viewer in Preview view. */
  openCodeFull({code:{lang:normalizeCodeLang('', code), body:String(code||'')}}, 'preview');
}
/* =============== Full-size code / preview viewer ===============
   cfOpen mirrors the canvas rule: only a real user tap opens it,
   and guardPreviewsClosed() keeps it hidden otherwise, so a
   keyboard open/close can never resurrect it. */
var cfMsg=null, cfOpen=false, cfView='code';
function openCodeFull(m, view){
  if(!m || !m.code) return;
  cfMsg=m; cfOpen=true;
  var runnable=codeIsRunnable(m.code);
  $('#cfTitle').textContent=(m.code.lang||'code')+' · '+codeLineCount(m.code.body)+' lines';
  $('#cfMeta').textContent=runnable? 'Preview fills the screen · code scrolls here' : 'Scroll to read the full code';
  $('#cfCode').textContent=m.code.body;
  $('#cfFrame').srcdoc='';
  $('#cfTabPreview').style.display=runnable? '' : 'none';
  $('#codeFullView').hidden=false;
  setCfView(view==='preview' && runnable? 'preview' : 'code');
}
function setCfView(v){
  cfView=v;
  var runnable=cfMsg? codeIsRunnable(cfMsg.code) : false;
  if(v==='preview' && !runnable) v='code';
  cfView=v;
  $('#cfCode').hidden=(v!=='code');
  var fr=$('#cfFrame');
  fr.hidden=(v!=='preview');
  if(v==='preview' && cfMsg){ fr.srcdoc=cfMsg.code.body; }
  $('#cfTabCode').classList.toggle('sel', v==='code');
  $('#cfTabPreview').classList.toggle('sel', v==='preview');
}
function closeCodeFull(){
  cfOpen=false; cfMsg=null;
  $('#codeFullView').hidden=true;
  $('#cfFrame').srcdoc='';
}
$('#cfBack').innerHTML=I.back;
$('#cfCopy').innerHTML=I.copy;
$('#cfBack').addEventListener('click',closeCodeFull);
$('#cfCopy').addEventListener('click',function(){ if(cfMsg && cfMsg.code) copyText(cfMsg.code.body); });
$('#cfTabCode').addEventListener('click',function(){ setCfView('code'); });
$('#cfTabPreview').addEventListener('click',function(){ setCfView('preview'); });
/* Code / Preview tabs INSIDE a chat code box: switch the pane in
   place — the box keeps its size, the code pane scrolls inside
   it, the preview pane runs the page inside it. */
document.addEventListener('click',function(e){
  var t=e.target.closest('[data-cbtab]'); if(!t) return;
  var box=t.closest('.codeblock'); if(!box) return;
  var want=t.getAttribute('data-cbtab');
  box.setAttribute('data-codeview', want);
  box.querySelectorAll('[data-cbtab]').forEach(function(x){ x.classList.toggle('sel', x.getAttribute('data-cbtab')===want); });
  box.querySelectorAll('[data-cbpane]').forEach(function(p){ p.hidden=(p.getAttribute('data-cbpane')!==want); });
  if(want==='preview') hydrateCodeFrames(box);
});
/* =============== Message menu (liquid glass) ===============
   Tapping (or long-pressing) ANY message — main chat or either
   split pane, user or assistant — opens one small minimal
   Apple-like liquid glass menu anchored to that message:
   Reply · Copy · Select · Share, then Edit on your own messages
   or Regenerate on assistant messages, then Delete. Every row
   works in place; nothing here is a dead control. The menu was
   not showing before because messages rendered with no id and
   no tap handler at all — both are fixed here and in msgHTML. */
var msgMenu=$('#msgMenu'), msgMenuCtx=null, msgMenuEl=null;
function msgFullText(m){
  var t=m.text||'';
  if(m.links && m.links.length) t+=(t?'\n':'')+m.links.map(function(e){return e.url;}).join('\n');
  if(m.attachments && m.attachments.length) t+=(t?'\n':'')+m.attachments.map(function(a){return typeof a==='string'?a:(a.name||'File');}).join('\n');
  return t+(m.code? '\n\n'+m.code.body : '');
}
function closeMsgMenu(){
  msgMenu.classList.remove('show'); msgMenu.innerHTML=''; msgMenuCtx=null;
  if(msgMenuEl){ msgMenuEl.classList.remove('menu-open'); msgMenuEl=null; }
}
function renderReplyBar(){
  var bar=$('#replyBar'); if(!bar) return;
  var rt=state.replyTo;
  if(!rt){ bar.className=''; bar.innerHTML=''; return; }
  bar.className='show';
  bar.innerHTML='<span class="rb-label">Reply</span><span class="rb-text">'+esc(rt.text)+'</span><button id="replyCancel" aria-label="Cancel reply">'+I.x+'</button>';
  $('#replyCancel').addEventListener('click',function(){ state.replyTo=null; renderReplyBar(); });
}
function openMsgMenuFor(msgEl){
  if(!msgEl) return;
  var id=msgEl.getAttribute('data-msg-id'), cid=msgEl.getAttribute('data-chat-id');
  var chat=chatById(cid), m=findMsg(chat,id);
  if(!m){ for(var i=0;i<chats.length && !m;i++){ var f=findMsg(chats[i],id); if(f){ chat=chats[i]; m=f; } } }
  if(!m||!chat) return;
  if(msgMenuCtx && msgMenuCtx.msg.id===m.id && msgMenu.classList.contains('show')){
    /* A fresh tap on the same message toggles its menu closed; the
       duplicate guard keeps the pointer tap + its click (one real
       tap) from toggling it straight back. */
    if(Date.now()-lastMsgMenuOpen.at<600) return;
    lastMsgMenuOpen={key:m.id, at:Date.now()}; closeMsgMenu(); return;
  }
  closePop(); closeMsgMenu();
  msgMenuCtx={chat:chat, msg:m}; msgMenuEl=msgEl; msgEl.classList.add('menu-open');
  var items=[
    {a:'reply', icon:I.reply, label:'Reply'},
    {a:'copy', icon:I.copy, label:'Copy'},
    {a:'select', icon:I.select, label:'Select'},
    {a:'share', icon:I.share, label:'Share'}
  ];
  if(m.role==='user') items.push({a:'edit', icon:I.edit, label:'Edit'});
  else items.push({a:'regen', icon:I.refresh, label:'Regenerate'});
  items.push({sep:true});
  items.push({a:'delete', icon:I.trash, label:'Delete', danger:true});
  /* Reaction options lead the menu — they show on EVERY selected
     message (yours and the agent's). The quick set is drawn from
     the app's own reaction palette when it is loaded. */
  var quick=['😂','😍','🔥','😮','😭','🫶','✨'];
  if(typeof REACTION_SET!=='undefined') quick=quick.filter(function(e){ return REACTION_SET[e]; });
  var reactHTML='<div class="msg-react-row" role="group" aria-label="React to this message">'
    +quick.map(function(e){ return '<button data-mr="'+escA(e)+'" class="'+(m.reaction===e?'sel':'')+'" aria-label="React '+escA(e)+'">'+e+'</button>'; }).join('')+'</div>';
  msgMenu.innerHTML=reactHTML+items.map(function(it){
    if(it.sep) return '<div class="msep"></div>';
    return '<button data-ma="'+it.a+'" class="'+(it.danger?'danger':'')+'" role="menuitem">'+it.icon+'<span>'+it.label+'</span></button>';
  }).join('');
  /* Anchor to the message: user menus right-align to the bubble,
     assistant menus left-align to the text; flips above the message
     when there is no room below, and always stays on screen. */
  var anchor=msgEl.querySelector('.bubble-user')||msgEl.querySelector('.body')||msgEl;
  var aRect=anchor.getBoundingClientRect(), vRect=msgEl.getBoundingClientRect();
  var w=224, est=items.length*45+16+54;
  var left=(m.role==='user') ? aRect.right-w : aRect.left;
  left=Math.max(8, Math.min(left, window.innerWidth-w-8));
  var top=vRect.bottom+6;
  if(top+est>window.innerHeight-8) top=Math.max(8, vRect.top-est-6);
  msgMenu.style.left=left+'px'; msgMenu.style.top=top+'px';
  msgMenu.style.transformOrigin=(m.role==='user'?'top right':'top left');
  msgMenu.classList.add('show');
  lastMsgMenuOpen={key:m.id, at:Date.now()};
  msgMenu.querySelectorAll('[data-ma]').forEach(function(b){
    b.addEventListener('click',function(){ var a=b.getAttribute('data-ma'); var ctx=msgMenuCtx; closeMsgMenu(); if(ctx) handleMsgAction(a, ctx.chat, ctx.msg); });
  });
  msgMenu.querySelectorAll('[data-mr]').forEach(function(b){
    b.addEventListener('click',function(){
      var e=b.getAttribute('data-mr'); var ctx=msgMenuCtx; closeMsgMenu();
      if(!ctx) return;
      if(ctx.msg.reaction===e) delete ctx.msg.reaction;
      else ctx.msg.reaction=e;
      renderAll();
    });
  });
}
var lastMsgMenuOpen={key:'', at:0};
function handleMsgAction(a, chat, m){
  if(a==='copy'){ copyText(msgFullText(m)); }
  else if(a==='reply'){
    state.replyTo={chatId:chat.id, msgId:m.id, role:m.role, text:msgFullText(m).replace(/\s+/g,' ').slice(0,140)};
    renderReplyBar(); input.focus(); toast('Replying — type your answer');
  }
  else if(a==='select'){
    openSheet('<h3>Select text</h3><p class="sub">Tap and hold, or use Select all, to take any part of this message.</p>'
      +'<div class="field"><textarea id="selMsgText" rows="6" readonly>'+esc(msgFullText(m))+'</textarea></div>'
      +'<button class="btn-primary" id="selAllBtn">Select all</button><button class="btn-ghost" id="selCopyBtn">Copy text</button><button class="btn-ghost" id="selDoneBtn">Done</button>');
    $('#selAllBtn').addEventListener('click',function(){ var t=$('#selMsgText'); t.focus(); t.select(); });
    $('#selCopyBtn').addEventListener('click',function(){ copyText(msgFullText(m)); });
    $('#selDoneBtn').addEventListener('click',closeSheet);
  }
  else if(a==='share'){
    var t=msgFullText(m);
    if(navigator.share){ navigator.share({text:t}).catch(function(){}); }
    else copyText(t);
  }
  else if(a==='edit'){
    openSheet('<h3>Edit message</h3><div class="field"><textarea id="editMsgText" rows="5">'+esc(m.text)+'</textarea></div>'
      +'<button class="btn-primary" id="editMsgSave">Save</button><button class="btn-ghost" id="editMsgCancel">Cancel</button>');
    $('#editMsgSave').addEventListener('click',function(){
      var v=$('#editMsgText').value.trim(); if(!v){ toast('Message is empty'); return; }
      m.text=v; closeSheet(); renderAll(); toast('Message edited');
    });
    $('#editMsgCancel').addEventListener('click',closeSheet);
  }
  else if(a==='regen'){
    var idx=chat.messages.indexOf(m), prev='';
    for(var i=idx-1;i>=0;i--){ if(chat.messages[i].role==='user'){ prev=chat.messages[i].text; break; } }
    if(providerRouteOn()){ var oldCode=m.code||null; chat.messages.splice(idx,1); renderAll(); callProvider(chat, null, oldCode? {contextCode:oldCode} : null); toast('Regenerating…'); return; }
    toast('Regenerating…');
    setTimeout(function(){
      if(m.code){ var r=codeReply(prev||'a small example'); m.text=r.text; m.code=r.code; }
      else m.text=localReply(prev||m.text, state.memory? searchMemory(prev||m.text) : []);
      renderAll(); toast('Regenerated');
    },450);
  }
  else if(a==='delete'){
    openSheet('<h3>Delete this message?</h3><p class="sub">'+esc(msgFullText(m).slice(0,120))+'</p>'
      +'<button class="btn-danger" id="msgDelYes">Delete</button><button class="btn-ghost" id="msgDelNo">Cancel</button>');
    $('#msgDelYes').addEventListener('click',function(){
      var ix=chat.messages.indexOf(m); if(ix>=0) chat.messages.splice(ix,1);
      if(state.replyTo && state.replyTo.msgId===m.id){ state.replyTo=null; renderReplyBar(); }
      closeSheet(); renderAll(); toast('Message deleted');
    });
    $('#msgDelNo').addEventListener('click',closeSheet);
  }
}
/* Tap detection: a tap is a short press that barely moves, so
   scrolling up/down, sidebar swipes and row swipes never open the
   menu by accident; a 560ms long press opens it too (Apple-style).
   Buttons inside a message (Play, Copy) keep their own jobs and
   never open it. The click fallback covers mouse clicks and any
   tap the pointer stream misses; a 600ms duplicate guard stops
   the pointer tap and its click from opening it twice. */
var msgTap=null, msgTapTimer=null;
function msgTapClear(){ msgTap=null; if(msgTapTimer){ clearTimeout(msgTapTimer); msgTapTimer=null; } }
document.addEventListener('pointerdown',function(e){
  if(msgMenu.classList.contains('show') && !msgMenu.contains(e.target) && !e.target.closest('.msg[data-msg-id]')) closeMsgMenu();
  if(e.target.closest('#msgMenu,.sheet,#settingsView,#sidebar')) { msgTapClear(); return; }
  if(e.target.closest('button,a,input,textarea,select')) { msgTapClear(); return; }
  var msgEl=e.target.closest('.msg[data-msg-id]'); if(!msgEl){ msgTapClear(); return; }
  msgTap={x:e.clientX, y:e.clientY, el:msgEl};
  msgTapTimer=setTimeout(function(){ if(msgTap){ var el2=msgTap.el; msgTapClear(); openMsgMenuFor(el2); } },560);
},{passive:true});
document.addEventListener('pointermove',function(e){
  if(msgTap && (Math.abs(e.clientX-msgTap.x)>12 || Math.abs(e.clientY-msgTap.y)>12)) msgTapClear();
},{passive:true});
document.addEventListener('pointerup',function(e){
  if(!msgTap) return;
  var el2=msgTap.el; msgTapClear(); openMsgMenuFor(el2);
},{passive:true});
document.addEventListener('pointercancel',msgTapClear,{passive:true});
/* Double-tap to like: a second tap on the same message within 350ms
   likes it (or un-likes it) instead of opening the menu. The like
   shows as a heart badge on the message, and it is recorded in
   memory as a preference signal — sanitised like all memory — so
   the agent knows what landed well and can use it later: liked
   messages surface through the same keyword memory search that
   runs before replies. */
var LIKE_HEART='<svg viewBox="0 0 24 24" fill="currentColor" stroke="none" style="width:12px;height:12px;display:block"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.65l-1-1.05a5.5 5.5 0 0 0-7.8 7.8l1.05 1.05L12 21.2l7.75-7.75 1.05-1.05a5.5 5.5 0 0 0 0-7.8z"/></svg>';
function recordLike(chat, m){
  var clean=memorySanitize(msgFullText(m)).slice(0,220);
  if(!clean) return;
  for(var i=0;i<MEM.length;i++) if(MEM[i].msgId==='like:'+m.id) return;
  var _lst=memStamp(Date.now()); MEM.push({id:'mem'+(++uid), msgId:'like:'+m.id, chatId:chat.id, chatTitle:chat.title, agent:memAgentName(), agentId:memAgentId(), role:'user', text:'Liked message — a preference signal; the user double-tapped this: '+clean, keys:memoryKeywords(clean), ts:Date.now(), date:_lst.date, time:_lst.time, when:_lst.label});
}
function removeLike(chat, m){
  for(var i=MEM.length-1;i>=0;i--) if(MEM[i].msgId==='like:'+m.id) MEM.splice(i,1);
}
var likeToastShown=false;
function toggleLike(chat, m){
  m.liked=!m.liked;
  if(m.liked){ recordLike(chat, m); if(!likeToastShown){ likeToastShown=true; toast('Liked — saved as a preference signal'); } }
  else removeLike(chat, m);
  renderAll();
}
var lastTapLike={id:'', at:0}, likeDown=null;
document.addEventListener('pointerdown',function(e){
  likeDown={x:e.clientX, y:e.clientY};
},{passive:true});
document.addEventListener('pointerup',function(e){
  if(!likeDown) return;
  var moved=Math.abs(e.clientX-likeDown.x)>12 || Math.abs(e.clientY-likeDown.y)>12;
  likeDown=null;
  if(moved) return;
  if(e.target.closest && e.target.closest('button,a,input,textarea,select,.sheet,#msgMenu')) return;
  var msgEl=e.target.closest && e.target.closest('.msg[data-msg-id]'); if(!msgEl) return;
  var id=msgEl.getAttribute('data-msg-id'), now=Date.now();
  if(lastTapLike.id===id && now-lastTapLike.at<350){
    lastTapLike={id:'', at:0};
    var chat=chatById(msgEl.getAttribute('data-chat-id')), m=findMsg(chat,id);
    if(m){ closeMsgMenu(); toggleLike(chat, m); }
  } else {
    lastTapLike={id:id, at:now};
  }
},{passive:true});
document.addEventListener('click',function(e){
  if(e.target.closest('button,a,input,textarea,select,.sheet,#msgMenu')) return;
  if(window.__axoSuppressMsgClick && Date.now()<window.__axoSuppressMsgClick) return; /* a swipe-to-reply just ended here */
  var msgEl=e.target.closest('.msg[data-msg-id]'); if(!msgEl) return;
  if(lastMsgMenuOpen.key===msgEl.getAttribute('data-msg-id') && Date.now()-lastMsgMenuOpen.at<600) return;
  openMsgMenuFor(msgEl);
});
document.addEventListener('keydown',function(e){
  if(e.key==='Escape') closeMsgMenu();
  /* Keyboard: Enter or Space on a focused message opens its menu,
     so the menu is fully usable on desktop without a mouse. */
  if((e.key==='Enter'||e.key===' ') && e.target && e.target.classList && e.target.classList.contains('msg')){
    e.preventDefault(); openMsgMenuFor(e.target);
  }
});
document.addEventListener('scroll',function(e){
  if(msgMenu.classList.contains('show') && e.target && e.target.closest && e.target.closest('#chatScroll,.pane-scroll,.sb-scroll,.set-scroll')) closeMsgMenu();
},true);
/* =============== Swipe to reply ===============
   Swiping a message RIGHT (mobile touch or desktop mouse drag) replies
   to that exact message: the reply bar arms above the composer and the
   message is quoted in the next send — the same Reply the message menu
   offers. The message follows the finger a little as feedback, then
   snaps back. Direction lock keeps vertical scrolling untouched, a
   leftward swipe keeps its existing job (opening the chats menu in the
   message area), and the click that ends the swipe is suppressed so
   the message menu never pops open on top of the reply. */
(function(){
  var g=null;
  function begin(t,x,y){
    if(!t || !t.closest) { g=null; return; }
    if(t.closest('#sidebar,#settingsView,.sheet,.menu-pop,#composerZone,header,button,a,input,textarea,select,.codeblock pre')) { g=null; return; }
    var m=t.closest('.msg[data-msg-id]');
    g=m? {el:m, x:x, y:y, locked:null, fired:false} : null;
  }
  function fireReply(){
    if(!g) return;
    var msgEl=g.el, id=msgEl.getAttribute('data-msg-id'), cid=msgEl.getAttribute('data-chat-id');
    var chat=chatById(cid), m=findMsg(chat,id);
    if(!m){ for(var i=0;i<chats.length && !m;i++){ var f=findMsg(chats[i],id); if(f){ chat=chats[i]; m=f; } } }
    g.fired=true;
    msgEl.style.transition='transform .22s cubic-bezier(.32,.72,0,1)'; msgEl.style.transform='';
    msgTapClear(); closeMsgMenu();
    window.__axoSuppressMsgClick=Date.now()+500;
    if(!m || !chat) return;
    state.replyTo={chatId:chat.id, msgId:m.id, role:m.role, text:msgFullText(m).replace(/\s+/g,' ').slice(0,140)};
    renderReplyBar(); input.focus();
    toast('Replying — type your answer');
  }
  function drag(x,y){
    if(!g || g.fired) return;
    var dx=x-g.x, dy=y-g.y;
    if(!g.locked){
      if(Math.abs(dy)>10 && Math.abs(dy)>=Math.abs(dx)) g.locked='v';
      else if(dx>14 && Math.abs(dx)>Math.abs(dy)*1.5) g.locked='h';
    }
    if(g.locked==='h'){
      msgTapClear();
      g.el.style.transition='none';
      g.el.style.transform='translateX('+Math.min(72, Math.max(0, dx*0.55))+'px)';
      if(dx>=72) fireReply();
    }
  }
  function finish(){
    if(g && g.el && !g.fired){ g.el.style.transition='transform .22s cubic-bezier(.32,.72,0,1)'; g.el.style.transform=''; }
    g=null;
  }
  document.addEventListener('touchstart',function(e){ var t=e.touches[0]; if(t) begin(e.target,t.clientX,t.clientY); },{passive:true});
  document.addEventListener('touchmove',function(e){ var t=e.touches[0]; if(t) drag(t.clientX,t.clientY); },{passive:true});
  document.addEventListener('touchend',finish,{passive:true});
  document.addEventListener('touchcancel',finish,{passive:true});
  document.addEventListener('pointerdown',function(e){ if(e.pointerType==='touch') return; begin(e.target,e.clientX,e.clientY); },{passive:true});
  document.addEventListener('pointermove',function(e){ if(e.pointerType==='touch') return; if(e.buttons) drag(e.clientX,e.clientY); },{passive:true});
  document.addEventListener('pointerup',function(e){ if(e.pointerType==='touch') return; finish(); },{passive:true});
  document.addEventListener('pointercancel',function(e){ if(e.pointerType==='touch') return; finish(); },{passive:true});
})();
/* =============== AI reactions ===============
   Instructions for the AI (built in): you may react to a user message
   with ONE emoji from the reaction set below — casually, sparingly,
   and only when it genuinely fits that message's mood (a joke, good
   news, affection, sadness, a celebration). Never react to plain
   questions, technical or study messages, commands, or link/file-only
   messages, and never react to every message or twice in a row in the
   same chat. The reaction appears as a small badge on the user's own
   message. When a provider model is connected, the same instructions
   are sent with the request and its chosen reaction is honoured.
   The set is segmented by grapheme so the ZWJ emojis stay intact. */
var REACTION_SRC='🫠🥶🫶😂😶‍🌫️🥹😅😭✨🫴💋😘😳🙂‍↔️🔥💦🌝☠️😚🎀🎉🕺😮🤍😍🥰🥲🫢😑😐🤨🫡🤔🫣😶🫥😏🙄😮‍💨😪😔🤢🤮🤕😷😴🥵🥶🥸😎🧐🫤🙁💩💗😿🙀👿😈👾👻🙊🙉🙈';
var REACTION_EMOJIS=(function(){
  var fallback=['😂','🥰','🔥','🎉','🤔','😴','🫠','✨','🫶','🤍','😅','🥹','😔','🤕','☠️','😍','😘','😎','💗','🕺'];
  try{
    var seg=new Intl.Segmenter('en',{granularity:'grapheme'}), out=[], seen={};
    Array.prototype.forEach.call(seg.segment(REACTION_SRC),function(s){ if(!seen[s.segment]){ seen[s.segment]=1; out.push(s.segment); } });
    return out.length>20? out : fallback;
  }catch(e){ return fallback; }
})();
var REACTION_SET={}; REACTION_EMOJIS.forEach(function(e){ REACTION_SET[e]=1; });
