  var idx=chat.messages.indexOf(m), prevUser=null;
  for(var i=idx-1;i>=0;i--){ if(chat.messages[i].role==='user'){ prevUser=chat.messages[i]; break; } }
  if(prevUser && prevUser.reaction) return;
