  pool.push({id:'mem'+(++uid), msgId:m.id, chatId:chat.id, chatTitle:chat.title, agent:an, agentId:aid, role:'user', text:full, keys:memoryKeywords(full), ts:ts, date:st.date, time:st.time, when:st.label});
