/* ONE TAP opens the side menu: the toggle acts on pointerdown,
   the moment the finger lands — it never waits for the click
   that follows pointerup, which a busy main thread, a keyboard
   dismissal or a WebView gesture quirk can swallow (the old
   "tap once, nothing happens" bug). The click that still
   follows is ignored for a beat, so one tap can never
   open-then-close; a plain mouse click still works on its own. */
var chatsBtnTapAt=0;
$('#chatsBtn').addEventListener('pointerdown',function(){ chatsBtnTapAt=Date.now(); setSidebar(!sbOpen(),true); });
$('#chatsBtn').addEventListener('click',function(){ if(Date.now()-chatsBtnTapAt<1200) return; setSidebar(!sbOpen(),true); });
/* Top-left companion to the chats button, same glass circle style,
   just smaller: + opens the + sheet. It never opens Settings. */
/* Header pill button: job follows the icon it is showing. Once the
   chat has started it shows the New chat (compose) icon, so a click
   starts a new chat — never Temporary chat. Before the first message
   it shows the Temporary chat icon and acts as the Temporary chat
   toggle. Temporary chat also has its own toggle row in the dots
   menu (handlePop 'temp'), which is the other place it can turn on. */
/* First-touch activation for BOTH header pill buttons, exactly
   like the chats button: they act on pointerdown — the moment the
   finger lands — never waiting for the click that follows
   pointerup, which a busy main thread, a keyboard dismissal or a
   WebView gesture quirk can swallow. That swallowed click was the
   remaining cause of "temp chat / new chat buttons not working
   inside the open chat": in an open chat these two buttons were
   the only header controls still click-only. The click that still
   follows is ignored for a beat, so one tap can never fire twice;
   a plain mouse click still works on its own. */
var tempBtnTapAt=0;
function tempBtnAction(){
  var c=currentChat();
  if(c && c.messages.length>0) newChat();
  else toggleTemp();
}
$('#tempBtn').addEventListener('pointerdown',function(){ tempBtnTapAt=Date.now(); tempBtnAction(); });
$('#tempBtn').addEventListener('click',function(){ if(Date.now()-tempBtnTapAt<1200) return; tempBtnAction(); });
var dotsBtnTapAt=0;
function dotsBtnAction(btn){
  /* Proper toggle: first tap opens, second tap on the same
     button closes — it never reopens an already-open menu. */
  if(pop.classList.contains('show') && popAnchor===btn){ closePop(); popCtx=null; return; }
  popCtx={chatId:state.currentId};
  openPop(btn.getBoundingClientRect(),[
    {id:'temp', icon:I.temp, label: state.temp?'Temporary chat: On':'Temporary chat: Off', dot:state.temp},
    {id:'split', icon:I.split, label: state.splitId?'Exit Split Screen':'Split Screen…'},
    {id:'share', icon:I.upload, label:'Share chat'},
    {sep:true},
    {id:'settings', icon:I.gear, label:'Settings'},
    {sep:true},
    {id:'clear', icon:I.trash, label:'Clear this chat', danger:true}
  ], btn);
}
$('#dotsBtn').addEventListener('pointerdown',function(){ dotsBtnTapAt=Date.now(); dotsBtnAction(this); });
$('#dotsBtn').addEventListener('click',function(){ if(Date.now()-dotsBtnTapAt<1200) return; dotsBtnAction(this); });
/* The API box (shown in the composer's place while no API is
   working): search and the status line open the API picker sheet —
   select / test / add, never in the top header — and the circular
   button where Send sits retests every API until one answers. */
$('#apiBoxSearch').addEventListener('click',function(){ openApiPicker(); });
$('#apiBoxMain').addEventListener('click',function(){ openApiPicker(); });
$('#apiBoxRetry').addEventListener('click',function(){
  /* Retry lives HERE — in the composer, exactly where Send sits
     — and it stays anchored with the composer above the keyboard.
     When the current chat's last word was a failed request (an
     API / limit error message), Retry re-runs that exact request
     (same flow as the old in-message Retry: drop the error,
     reset relay detection, send again). Otherwise it re-tests
     every API, as before. */
  var c=(typeof currentChat==='function')? currentChat() : null;
  var lm=c && c.messages.length? c.messages[c.messages.length-1] : null;
  if(lm && lm.role==='ai' && (lm.apiCta || lm.limitCta)){
    c.messages.pop();
    relayGone=false; relayStrikes=0;
    setApiHealth('changed');
    renderAll();
    if(providerRouteOn()) callProvider(c, null);
    else toast('Add an API key or turn on the Gptopen Model first');
    return;
  }
  testAllApis();
});
