  if(emo==='writing'||emo==='reading') return '<g><path d="M28 75 q10 -4.4 20 0 v13 q-10 -4.4 -20 0z" fill="#fff3d6" stroke="'+ink+'" stroke-width="1.6"/><path d="M68 75 q-10 -4.4 -20 0 v13 q10 -4.4 20 0z" fill="#ffe9bd" stroke="'+ink+'" stroke-width="1.6"/><path d="M48 75 v13" stroke="'+ink+'" stroke-width="1.6"/></g>';
  if(emo==='searching') return '<g><circle cx="48" cy="80" r="8.5" fill="#bfe3ff" opacity=".55"/><circle cx="48" cy="80" r="5" fill="#e8f6ff" opacity=".8"/><path class="char-spark" d="M48 74.6 l1.2 2.9 2.9 1.2 -2.9 1.2 -1.2 2.9 -1.2 -2.9 -2.9 -1.2 2.9 -1.2z" fill="#5b9dff"/></g>';
